def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid for _ in row))
    # Each isolated interior pixel becomes a 4; extend its color horizontally
    # toward the opposing edge of the grid, stopping before that edge.
    for y in range(1, h - 1):
        for x in range(w):
            color = grid[y][x]
            if color == bg:
                continue
            if x < w // 2:
                for xx in range(x + 1, w - 1):
                    out[y][xx] = color
            else:
                for xx in range(1, x):
                    out[y][xx] = color
            out[y][x] = 4
    return out

