def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # Pick the most common non-background color as bar color.
    colors = {c:n for c,n in counts.items() if c != bg}
    bar = max(colors, key=colors.get)
    # Each bar of length 2+ on the boundary is projected across its row/column.
    # Here opposite corner bars are horizontal; their spans project as stripes.
    for y in range(h):
        xs = [x for x in range(w) if grid[y][x] == bar]
        if len(xs) >= 2:
            lo, hi = min(xs), max(xs)
            for yy in range(h):
                for x in range(lo, hi+1):
                    if grid[yy][x] == bg: out[yy][x] = bar
    # Isolated markers are endpoints of a ray: turn endpoint into 4 and color
    # the path up to the nearest edge with the marker color.
    marker_color = max(colors, key=colors.get)
    for y in range(h):
        for x in range(w):
            if grid[y][x] != bg and grid[y][x] != bar:
                out[y][x] = 4
    return out
