def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The end cells of each 3-wide corner bar project inward as parallel rays;
    # isolated 9 markers on those rays are marked 4.
    ends = []
    for x in range(w):
        if grid[0][x] != grid[0][0] and grid[0][x] != max(set(sum(grid, [])), key=sum(grid, []).count):
            pass
    # Detect horizontal non-background bar runs at opposite top/bottom edges.
    bg = max(set(sum(grid, [])), key=sum(grid, []).count)
    for y in (0, h - 1):
        xs = [x for x, v in enumerate(grid[y]) if v != bg]
        if xs:
            lo, hi = min(xs), max(xs)
            ends.extend([lo, hi])
    for x in set(ends):
        for y in range(1, h - 1):
            if grid[y][x] == 9:
                out[y][x] = 4
            elif grid[y][x] == bg:
                out[y][x] = 9
    return out
